#!/usr/bin/env python3
"""Build the agent/iife bundle.

- Uses agent/injected.js (original FRIDA_JS with skipInterfaceExpansion added)
- Imports frida-java-bridge and attaches it to globalThis.Java
- Outputs an IIFE bundle instead of Frida's custom package format
  (ESM format causes Script.create_script() to fail with "malformed package")
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
AGENT = ROOT / "agent"


def main() -> int:
    injected = (AGENT / "injected.js").read_text(encoding="utf-8")
    entry = (
        "// Auto-generated by scripts/build_agent.py (do not edit directly; edit agent/injected.js)\n"
        "import Java from 'frida-java-bridge';\n"
        "globalThis.Java = Java;\n\n"
        + injected
    )
    (AGENT / "agent.js").write_text(entry, encoding="utf-8")

    try:
        import frida
    except ImportError:
        print("frida (python) not found. Run scripts/setup.sh first", file=sys.stderr)
        return 1

    if not (AGENT / "node_modules" / "frida-java-bridge").is_dir():
        print("agent/node_modules not found. Run `npm install` inside agent/", file=sys.stderr)
        return 1

    compiler = frida.Compiler()
    bundle = compiler.build("agent.js", project_root=str(AGENT), bundle_format="iife")
    out = AGENT / "agent.iife.js"
    out.write_text(bundle, encoding="utf-8", newline="")
    print(f"built {out.relative_to(ROOT)} ({len(bundle)} chars)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
